function SmoothLink({href,children,className=""}){
  const click=e=>{if(href&&href.startsWith("#")){e.preventDefault();const el=document.querySelector(href);if(el)el.scrollIntoView({behavior:"smooth",block:"start"})}};
  return <a href={href||"#"} className={className} onClick={click} target={href&&href.startsWith("http")?"_blank":undefined} rel={href&&href.startsWith("http")?"noopener noreferrer":undefined}>{children}</a>;
}

