function ProPlus(){return <TD n="04" name="SootyEdge Key Levels" sub="Your Daily Signal Levels — Drawn For You" accent="#FFD600" body="Get your daily signal levels — Entry, Stop Loss, and five Take Profit targets — automatically plotted on every chart, every session. Live risk-to-reward on every target. Adapts direction live based on price action." builtFor="traders who want to stop drawing lines manually and start executing with a predefined plan." panel={<div className="neon-p">{[{n:"TP 5",c:"#006B2A"},{n:"TP 4",c:"#006B2A"},{n:"TP 3",c:"#006B2A"},{n:"TP 2",c:"#006B2A"},{n:"TP 1",c:"#006B2A"},{n:"ENTRY",c:"#FFD600"},{n:"SL",c:"#8A0000"}].map((l,i)=><div key={i} className="nr"><span className="nl" style={{color:"#fff"}}>{l.n}</span><div className="nw"><div className="nb" style={{background:l.c}}/></div></div>)}</div>} feats={[{d:"#FFD600",t:"Entry, Stop & 5 Take Profits",b:"TP1 through TP5 drawn automatically on every chart, every session."},{d:"#FFD600",t:"Live Risk-to-Reward Per Target",b:"Every TP carries a live R:R label so you size positions with intent, not guesswork."},{d:"#FFD600",t:"Auto / Long / Short Modes",b:"Adapts direction live based on price action, or pin it to a single bias when you have your read."},{d:"#FFD600",t:"Multi-Timeframe Confluence Zones",b:"Highlights areas where pivot levels align across timeframes — your highest-probability windows."},{d:"#FFD600",t:"Dynamic Webhook Alerts",b:"Full level data fires on every event — wire it straight into your broker or automation."},{d:"#FFD600",t:"Historical Level Retention",b:"Configurable lookback so you can review prior sessions and back-test the plan against actual price."}]}/>}

function Benefits(){return(<Sec id="benefits" ey="KEY BENEFITS" center><h2 className="sec-h2 rv"><span className="hw">What SootyEdge</span><br/><span className="hd">gives you.</span></h2><div className="ben-g">{[{v:"1",l:"Clear Signal",b:"One table. One verdict. No conflicting indicators.",c:"#FFD600"},{v:"7",l:"Levels Drawn",b:"Entry, SL, TP1–5 plotted every session automatically.",c:"#FFD600"},{v:"0",l:"Guesswork",b:"The system tells you where to enter, stop, and exit.",c:"#FFD600"},{v:"∞",l:"Markets",b:"Stocks, forex, crypto, futures. Any TradingView market.",c:"#FFD600"},{v:"24",l:"Hour Alerts",b:"Webhook alerts monitor the market around the clock.",c:"#FFD600"},{v:"4",l:"Tools, 1 Edge",b:"Four indicators in one seamless framework.",c:"#FFD600"}].map((b,i)=><div key={i} className="ben-c rv hov"><Counter value={b.v} color={b.c}/><div className="ben-l">{b.l}</div><p className="ben-b">{b.b}</p></div>)}</div></Sec>)}

