function Pricing(){const[period,setPeriod]=useState("monthly");const ann=period==="annual";return(<Sec id="pricing" ey="PRICING" center><h2 className="sec-h2 rv"><span className="hw">Choose your</span><br/><span className="hd">access level.</span></h2><p className="sec-lead rv">Both tiers include the full four-indicator suite. Inner Circle adds the private community where the system gets traded live.</p><div className="bill-toggle rv" role="tablist" aria-label="Billing period"><button role="tab" aria-selected={!ann} className={`bt-opt hov${!ann?" bt-on":""}`} onClick={()=>setPeriod("monthly")}>Monthly</button><button role="tab" aria-selected={ann} className={`bt-opt hov${ann?" bt-on":""}`} onClick={()=>setPeriod("annual")}>Annual<span className="bt-save">2 MO FREE</span></button></div><div className="pr-g">{TIERS.map(t=>{const price=ann?t.annual:t.monthly;const per=ann?"/ year · billed annually":"/ month · cancel anytime";const href=ann?t.annualHref:t.monthlyHref;return(<div key={t.id} className={`pr-c rv hov${t.popular?" pr-feat pr-popular":""}`}>{t.popular&&<div className="pr-pop">MOST POPULAR</div>}<div className="prt">{t.tag}</div><div className="prn">{t.name}</div><p className="prd">{t.desc}</p><div className="prp"><span className="prc">$</span><span className="prv">{price.toLocaleString()}</span></div><span className="prper">{per}</span>{ann&&<span className="pr-save">{t.annualSave}</span>}<ul className="pr-feats">{t.features.map(([f,ok],fi)=><li key={fi} className={ok?"pr-yes":"pr-no"}><span className="pr-chk">{ok?"✓":"✗"}</span>{f}</li>)}</ul><MagBtn href={href} className={t.popular?"btn-p":"btn-g"} style={{width:"100%",textAlign:"center",marginTop:20}}>{t.cta.toUpperCase()} →</MagBtn><a href="/refund-policy" className="pr-disc hov">By purchasing, you agree to the No-Refund Policy.</a></div>)})}</div><script type="application/ld+json" dangerouslySetInnerHTML={{__html:JSON.stringify({"@context":"https://schema.org","@graph":TIERS.map(t=>({"@type":"Product","name":`SootyEdge ${t.name}`,"description":t.desc,"brand":{"@type":"Brand","name":"SootyEdge"},"offers":[{"@type":"Offer","price":t.monthly,"priceCurrency":"USD","name":`${t.name} — Monthly`,"availability":"https://schema.org/InStock","url":t.monthlyHref},{"@type":"Offer","price":t.annual,"priceCurrency":"USD","name":`${t.name} — Annual`,"availability":"https://schema.org/InStock","url":t.annualHref}]}))})}}/></Sec>)}

function Requirements(){const items=[{t:"TradingView Premium",b:"Active Premium plan required for multi-timeframe data — SootyEdge Flow Tracker and Key Levels confluence both depend on it."},{t:"Funded Account",b:"A funded brokerage or prop-firm account in your name. SootyEdge does not provide capital or take any cut of P&L."},{t:"Time To Learn",b:"This is a system, not a signal feed. Plan an afternoon to walk the workflow and another week of paper trades before going live."}];return(<Sec ey="REQUIREMENTS" center><h2 className="sec-h2 rv"><span className="hw">What you'll</span><br/><span className="hd">need.</span></h2><p className="sec-lead rv">Three things to run the suite. Nothing else.</p><div className="req-g rv">{items.map((it,i)=><div key={i} className="req-c hov"><div className="req-n">0{i+1}</div><div className="req-t">{it.t}</div><p className="req-b">{it.b}</p></div>)}</div></Sec>)}

