function FAQ(){const[o,setO]=useState(null);const qs=[{q:"What markets do the indicators work on?",a:"Any market available on TradingView. The suite is optimized for futures and forex, with separate presets for stocks and options. The indicators run on stocks, ETFs, indices, crypto, forex, futures, and commodities — anywhere TradingView serves OHLC data."},{q:"Do I need TradingView Premium?",a:"Yes for full functionality. Multi-timeframe features — SootyEdge Flow Tracker's higher-timeframe grading and Key Levels confluence detection — both require Premium for the second timeframe data feed. The core indicators load on lower tiers but you'll hit TradingView's script and timeframe limits."},{q:"Are these signals I can copy?",a:"No. SootyEdge is decision support, not signal copy-trading. You see direction, levels, and a pre-mapped trade plan — you execute on your account, in your size, with your risk parameters. We don't push trades to you and we don't manage capital."},{q:"Can I cancel anytime?",a:"Yes. Both monthly and annual subscriptions can be cancelled at any time from the Stripe customer portal in your confirmation email. Access continues until the end of the billing period you've already paid for."},{q:"Do you offer refunds?",a:"No. Due to the immediate digital delivery of indicator access and Inner Circle materials, all sales are final. You'll be asked to acknowledge the No-Refund Policy before checkout."},{q:"How quickly do I get access?",a:"TradingView indicator invites are sent within 24 hours of payment confirmation — usually within minutes during US market hours. Inner Circle Discord invite arrives in the same email."},{q:"What if my TradingView access has issues?",a:"Email support@sootyedge.com with your purchase email and TradingView username. We re-issue indicator invites manually within one business day, no questions asked."},{q:"Is this financial advice?",a:"No. SootyEdge provides trading software and educational content. Nothing on this site or in any indicator output constitutes financial, investment, or trading advice. Trading involves substantial risk of loss. You are solely responsible for your trading decisions and outcomes."}];return(<Sec id="faq" ey="FAQ"><h2 className="sec-h2 rv"><span className="hw">Common</span><br/><span className="hd">questions.</span></h2><div className="faq-l rv" style={{maxWidth:780}}>{qs.map((q,i)=><div key={i} className={`faq-i hov${o===i?" faq-o":""}`} onClick={()=>setO(o===i?null:i)}><div className="faq-q"><span>{q.q}</span><span className="faq-arr">{o===i?"−":"+"}</span></div>{o===i&&<p className="faq-a">{q.a}</p>}</div>)}</div></Sec>)}

function FinalCTA(){return(<section className="fcta"><div className="fcta-glow"/><div className="fcta-badge rv"><span className="ldot"/>LIVE SYSTEM · ACTIVE</div><div className="sec-ey rv" style={{justifyContent:"center"}}><span className="ey-line"/>THE EDGE IS ALREADY BUILT<span className="ey-line"/></div><h2 className="fcta-h rv"><span className="hw">The only question is</span><br/><span className="hw">who uses it first.</span></h2><p className="fcta-sub rv">One indicator. One framework. Full discipline from signal to exit.</p><div className="fcta-acts rv"><MagBtn href="#pricing">ACCESS THE SYSTEM</MagBtn><MagBtn href="#chart" className="btn-g">VIEW LIVE CHART</MagBtn></div></section>)}

