export default function SootyEdge(){
  // Standalone Dex product lives at:
  //   - /dex on any host (path-based)
  //   - travelinginprofit.com / www.travelinginprofit.com (apex hostnames)
  //   - dex.* on any host (subdomain prefix)
  // Bare-host/pathname check is fine for a hard-navigated SPA.
  if (typeof window !== "undefined") {
    const path = window.location.pathname;
    const host = window.location.hostname;
    const dexHosts = new Set([
      "travelinginprofit.com",
      "www.travelinginprofit.com",
    ]);
    const isDexHost = dexHosts.has(host) || host.startsWith("dex.");
    const isDexPath = /^\/dex\/?$/.test(path);
    if (isDexHost || isDexPath) {
      return <Dex/>;
    }
  }

  useReveal();
  return(
    <>
      <style>{CSS}</style>
      <ConstellationBG/>
      <Spotlight/>
      <Cursor/>
      <Nav/>
      <Hero/>
      <Ticker/>
      <LiveScreenshot/>
      <Problem/>
      <SystemIntro/>
      <ActionZones/>
      <FlowTrackerPro/>
      <SootyDot/>
      <ProPlus/>
      <Workflow/>
      <Benefits/>
      <Reviews/>
      <Personas/>
      <Pricing/>
      <Requirements/>
      <FAQ/>
      <FinalCTA/>
      <Disclosure/>
      <Footer/>
    </>
  )
}
